-- Add 9 missed repeater signals, each inserted just before its parent (parent row - 5)
-- in CSMT_PNVL_DN_HB / CSMT_PNVL_UP_HB / CSMT_KYN_DN_TH. Additive; local then prod.
-- Re-run magnet backfill after (magnet_id starts NULL).


-- book rows: repeater just before its parent

SELECT sec.section_code, r.row_order, r.display_signal_no, r.display_location, sg.signal_type
FROM div_signal_book_rows r JOIN div_signal_book_sections sec ON sec.id=r.book_section_id JOIN div_signals sg ON sg.id=r.signal_id
WHERE sg.signal_number LIKE '% REP' AND sg.signal_number IN ('H-09 REP','H-13 REP','H-23 REP','MNKD S-4 REP','VSH S-5 REP','MNKD S-22 REP','K-035 REP','VK S-5 REP','K-4001 REP')
ORDER BY sec.section_code, r.row_order;
